import{_ as a,c as o,o as i,a5 as d}from"./chunks/framework.DuCYAsAJ.js";const b=JSON.parse('{"title":"Facebook Live Comments 系统设计","description":"","frontmatter":{"title":"Facebook Live Comments 系统设计","date":"2026-05-01T00:00:00.000Z","order":9},"headers":[],"relativePath":"posts/SystemDesign/fblivecomments.md","filePath":"posts/SystemDesign/fblivecomments.md","lastUpdated":1779463578000}'),c={name:"posts/SystemDesign/fblivecomments.md"};function r(t,e,l,n,s,m){return i(),o("div",null,[...e[0]||(e[0]=[d('<h2 id="facebook-live-comments-系统设计" tabindex="-1">Facebook Live Comments 系统设计 <a class="header-anchor" href="#facebook-live-comments-系统设计" aria-label="Permalink to &quot;Facebook Live Comments 系统设计&quot;">​</a></h2><p>本文设计的是一个类似 Facebook Live Comments 的直播评论系统。用户在观看直播时，可以实时发送评论、实时看到别人发的评论，并在刚进入直播间时先补到最近一段历史评论。它的核心不是“评论怎么存”，而是“评论怎么在极低延迟下广播给海量观众”。这意味着系统既要处理普通写库问题，也要处理长连接、实时推送、跨节点协调和 mega-stream 的流量爆炸问题。</p><h3 id="问题定义与边界" tabindex="-1">问题定义与边界 <a class="header-anchor" href="#问题定义与边界" aria-label="Permalink to &quot;问题定义与边界&quot;">​</a></h3><h4 id="功能需求" tabindex="-1">功能需求 <a class="header-anchor" href="#功能需求" aria-label="Permalink to &quot;功能需求&quot;">​</a></h4><p>观众能够在直播间发送评论；观众能够在观看直播时看到新评论不断出现；观众能够看到自己加入直播间之前已有的评论。</p><h4 id="非功能需求" tabindex="-1">非功能需求 <a class="header-anchor" href="#非功能需求" aria-label="Permalink to &quot;非功能需求&quot;">​</a></h4><ol><li>低延迟：评论应以接近实时的方式广播，典型目标是端到端 <code>&lt; 200ms</code></li><li>高可用：优先可用性，最终一致即可</li><li>高扩展：系统要能支撑数百万并发直播、以及单个热门直播每秒数千条评论</li></ol><h4 id="本文暂不展开" tabindex="-1">本文暂不展开 <a class="header-anchor" href="#本文暂不展开" aria-label="Permalink to &quot;本文暂不展开&quot;">​</a></h4><p>评论回复、评论点赞 / reaction、审核、反垃圾和敏感词、复杂鉴权。</p><h3 id="核心实体、接口与数据流" tabindex="-1">核心实体、接口与数据流 <a class="header-anchor" href="#核心实体、接口与数据流" aria-label="Permalink to &quot;核心实体、接口与数据流&quot;">​</a></h3><h4 id="核心实体" tabindex="-1">核心实体 <a class="header-anchor" href="#核心实体" aria-label="Permalink to &quot;核心实体&quot;">​</a></h4><p><code>LiveVideo</code>、<code>Comment</code>、<code>ViewerSession</code>、<code>RealtimeServer</code>。其中 <code>Comment</code> 最关键的字段通常包括 <code>commentId</code>、<code>liveVideoId</code>、<code>authorId</code>、<code>content</code>、<code>createdAt</code>。</p><h4 id="初始接口" tabindex="-1">初始接口 <a class="header-anchor" href="#初始接口" aria-label="Permalink to &quot;初始接口&quot;">​</a></h4><p>发评论：<code>POST /comments/{liveVideoId}</code>；拉历史评论：<code>GET /comments/{liveVideoId}?before={timestamp}&amp;limit={n}</code>；订阅实时评论：<code>GET /stream/{liveVideoId}</code>。这里 <code>before</code> 很关键，因为它天然支持“往上翻更早评论”的 infinite scroll，而不是只支持“某个时间点之后的新评论”。</p><h4 id="高层数据流" tabindex="-1">高层数据流 <a class="header-anchor" href="#高层数据流" aria-label="Permalink to &quot;高层数据流&quot;">​</a></h4><ol><li>用户进入直播间</li><li>客户端先调用 <code>GET /comments/{liveVideoId}</code> 拉最近一屏历史评论</li><li>同时建立实时订阅连接</li><li>有新评论时，服务端先持久化，再广播给正在观看的客户端</li><li>用户继续上滑时，再通过 <code>before + limit</code> 拉更早评论</li></ol><h3 id="核心架构设计" tabindex="-1">核心架构设计 <a class="header-anchor" href="#核心架构设计" aria-label="Permalink to &quot;核心架构设计&quot;">​</a></h3><h4 id="一、观众能够发送评论" tabindex="-1">一、观众能够发送评论 <a class="header-anchor" href="#一、观众能够发送评论" aria-label="Permalink to &quot;一、观众能够发送评论&quot;">​</a></h4><p>基础版本并不复杂：客户端调用 <code>POST /comments/{liveVideoId}</code>，<code>Comment Management Service</code> 校验请求，把评论写入数据库，返回成功。如果只看“发评论”这个功能，到这里已经成立。数据库本身不需要太复杂，重点是按 <code>liveVideoId</code> 查询某个直播间的评论、按时间倒序分页、写入吞吐足够高。因此比较自然的索引模型是主键或分区键包含 <code>liveVideoId</code>，排序键包含 <code>createdAt</code>。</p><h4 id="二、观众能够看到加入之前的评论" tabindex="-1">二、观众能够看到加入之前的评论 <a class="header-anchor" href="#二、观众能够看到加入之前的评论" aria-label="Permalink to &quot;二、观众能够看到加入之前的评论&quot;">​</a></h4><p>当用户进入直播间时，不能只看到新评论，还需要先补一屏历史记录。这条链路和聊天室、私信很像：先拉最近 N 条，用户继续上滑时，再按时间游标拿更旧的数据。因此 <code>GET /comments/{liveVideoId}?before={timestamp}&amp;limit={n}</code> 很合适：第一次不带 <code>before</code>，返回最近一屏；后续带上当前最旧评论的时间戳，再继续往前翻。这里要特别注意，不要把“历史拉取”和“实时推送”混成一条链路，它们的访问模式完全不同：历史评论更像普通分页查询，新评论更像实时广播。</p><h4 id="三、观众能够实时看到新评论" tabindex="-1">三、观众能够实时看到新评论 <a class="header-anchor" href="#三、观众能够实时看到新评论" aria-label="Permalink to &quot;三、观众能够实时看到新评论&quot;">​</a></h4><p>如果让客户端每隔几秒轮询一次，请求数量会非常大，延迟会明显增高，大量请求其实都在问“有没有新评论”。因此，直播评论更适合 push 模型，而不是 polling。这里两个常见选择是 <code>WebSocket</code> 和 <code>Server-Sent Events (SSE)</code>。在这个场景里，评论流动基本是<strong>服务端单向推送</strong>：客户端虽然会发评论，但完全可以通过普通 <code>POST</code> 请求完成；实时通道本身更主要承担“服务器不断把新评论推给观众”这个职责。因此，<code>SSE</code> 是一个贴合度很高的默认选择，它的语义本来就是单向推送，浏览器支持自然，也很适合“持续流式返回评论”的场景。基础实时方案可以写成：用户进入直播间时建立 SSE 连接，<code>Realtime Messaging Server</code> 记录这个连接正在观看哪个 <code>liveVideoId</code>，某条新评论创建后，服务器把评论通过 SSE 推给所有订阅该直播的连接。</p><h3 id="深入讨论" tabindex="-1">深入讨论 <a class="header-anchor" href="#深入讨论" aria-label="Permalink to &quot;深入讨论&quot;">​</a></h3><h4 id="一、为什么单机实时推送很快就不够用" tabindex="-1">一、为什么单机实时推送很快就不够用 <a class="header-anchor" href="#一、为什么单机实时推送很快就不够用" aria-label="Permalink to &quot;一、为什么单机实时推送很快就不够用&quot;">​</a></h4><p>单机版本里，<code>Realtime Server</code> 只需要在内存里维护一个 <code>liveVideoId -&gt; [viewerConnection1, viewerConnection2, ...]</code> 的映射，新评论一到，直接遍历对应连接并推送即可。但一旦系统要支撑数百万并发观看者，单机就会马上遇到瓶颈：长连接数量太多；文件描述符、内存、CPU 会成为限制；同一个直播的观众会被分散到多台机器。真正困难的不是“怎么多部署几台机器”，而是“新评论到了某一台机器后，怎么让其他机器上的观众也收到”。</p><h4 id="二、横向扩容后-服务器之间如何协调" tabindex="-1">二、横向扩容后，服务器之间如何协调 <a class="header-anchor" href="#二、横向扩容后-服务器之间如何协调" aria-label="Permalink to &quot;二、横向扩容后，服务器之间如何协调&quot;">​</a></h4><p>假设 <code>Viewer A</code> 正在 <code>Server 1</code> 上看 <code>LiveVideo 1</code>，<code>Viewer B</code> 正在 <code>Server 2</code> 上看 <code>LiveVideo 1</code>，如果一条新评论请求打到 <code>Server 1</code>，它很容易推给 <code>Viewer A</code>，但它并不知道 <code>Viewer B</code> 在 <code>Server 2</code>。这就需要一个跨节点协调层。</p><p>一个能工作的基础方案是 naive pub/sub：<code>Comment Management Service</code> 每创建一条评论，就向一个公共 channel 发布消息；所有 <code>Realtime Messaging Server</code> 都订阅这个 channel；每台服务器收到后，只把评论转发给本机正在观看该直播的连接。这个方案容易实现，但效率很低，因为每台服务器都会收到所有直播间的评论，即使它本机一个相关观众都没有，也要白白处理这条消息。</p><h4 id="三、如何改进-naive-pub-sub" tabindex="-1">三、如何改进 naive pub/sub <a class="header-anchor" href="#三、如何改进-naive-pub-sub" aria-label="Permalink to &quot;三、如何改进 naive pub/sub&quot;">​</a></h4><p>更合理的方向是分区式 pub/sub：不再只有一个全局 channel，而是把直播流映射到多个 channel，每台 <code>Realtime Server</code> 只订阅自己真正需要的那部分 channel，例如通过 <code>hash(liveVideoId) % N</code> 把直播分散到固定数量的 channel 上。</p><p>但这又会引出一个新问题：如果负载均衡是 round-robin，那么同一个直播的观众可能被打散到很多服务器上，于是很多服务器都得订阅同一个或很多个 channel，效率还是不理想。所以更进一步的解法是让观众尽量<strong>同播同服</strong>：Layer 7 负载均衡器根据 <code>liveVideoId</code> 做一致性路由，尽量把观看同一个直播的观众打到同一批 <code>Realtime Server</code>，这样每台服务器需要订阅的 channel 数量更少，也更容易把“收到一条评论后广播给本机连接”这件事做得高效。</p><h4 id="四、另一种思路-dispatcher-service" tabindex="-1">四、另一种思路：Dispatcher Service <a class="header-anchor" href="#四、另一种思路-dispatcher-service" aria-label="Permalink to &quot;四、另一种思路：Dispatcher Service&quot;">​</a></h4><p>除了 pub/sub，还可以使用更高级但更复杂的 <code>Dispatcher Service</code>。它的思路是反过来：不让所有 <code>Realtime Server</code> 自己订阅频道，而是维护一个中心路由器，记录“哪个直播现在在哪些服务器上有观众”。每来一条新评论，<code>Comment Service</code> 先问 Dispatcher，Dispatcher 直接把评论转发给那些目标服务器。这个方案的优点是路由逻辑集中、不需要复杂的动态订阅管理、可以做更细的路由策略；代价是状态一致性和运维复杂度更高。通常可以先采用分区式 pub/sub 作为基础方案，再把 Dispatcher 作为更深一层的演进方向。</p><h4 id="五、mega-stream-为什么不能再追求-每条评论都送到每个人" tabindex="-1">五、mega-stream 为什么不能再追求“每条评论都送到每个人” <a class="header-anchor" href="#五、mega-stream-为什么不能再追求-每条评论都送到每个人" aria-label="Permalink to &quot;五、mega-stream 为什么不能再追求“每条评论都送到每个人”&quot;">​</a></h4><p>mega-stream 是直播评论系统里很有代表性的极端场景。如果某个超级热点直播间每秒 <code>5000</code> 条评论，而用户界面只显示最近 <code>20</code> 条，那么每条评论可能只停留几毫秒，人类根本来不及阅读。这时系统目标就变了：重点不再是“每个观众看见每一条评论”，而是“让观众感受到实时热闹的氛围”。也就是说，到了 mega-stream 场景，<strong>完整送达每一条评论</strong>本身就不再有产品价值。</p><h4 id="六、mega-stream-的更合理策略-采样" tabindex="-1">六、mega-stream 的更合理策略：采样 <a class="header-anchor" href="#六、mega-stream-的更合理策略-采样" aria-label="Permalink to &quot;六、mega-stream 的更合理策略：采样&quot;">​</a></h4><p>因此，对超级热点直播间，更合理的方案是只展示一个代表性子集。最直接的办法是动态采样：评论量较小时，几乎全量推送；评论量极大时，只按一定比例抽样。例如 <code>100 comments/s</code> 时采样 <code>50%</code>，<code>5000 comments/s</code> 时采样 <code>1% ~ 2%</code>，这样每个观众仍能持续看到新评论滚动，但系统不再试图把所有评论都广播给所有人。</p><p>采样策略还可以继续变得更聪明：优先展示用户关注的人发的评论、优先展示有互动的评论、优先展示认证账号或高质量评论。这一步已经从“系统设计”自然延伸到了“产品体验优化”，也是这类系统很值得补充的思考。</p><h4 id="七、为什么历史评论和实时流要分层" tabindex="-1">七、为什么历史评论和实时流要分层 <a class="header-anchor" href="#七、为什么历史评论和实时流要分层" aria-label="Permalink to &quot;七、为什么历史评论和实时流要分层&quot;">​</a></h4><p>这里还有一个容易忽略的分层原则：历史评论适合查库分页，实时评论适合内存连接广播。如果让实时系统负责“所有历史回放”，或者让数据库承担“所有实时广播”，两边都会变差。因此更清晰的拆法是：<code>Comment Management Service + DB</code> 负责写入和历史查询；<code>Realtime Messaging Server</code> 负责低延迟推送；<code>Pub/Sub</code> 或 <code>Dispatcher</code> 负责跨节点协调。一旦这个分层说清楚，系统的大部分复杂度也就随之被拆开了。</p><h3 id="整体链路" tabindex="-1">整体链路 <a class="header-anchor" href="#整体链路" aria-label="Permalink to &quot;整体链路&quot;">​</a></h3><h4 id="发评论路径" tabindex="-1">发评论路径 <a class="header-anchor" href="#发评论路径" aria-label="Permalink to &quot;发评论路径&quot;">​</a></h4><ol><li>客户端请求 <code>POST /comments/{liveVideoId}</code></li><li><code>Comment Management Service</code> 持久化评论</li><li>服务把新评论事件发给协调层</li><li>相关 <code>Realtime Server</code> 收到事件</li><li>服务器将评论通过 SSE 推给本机正在观看该直播的观众</li></ol><h4 id="首次进入直播间路径" tabindex="-1">首次进入直播间路径 <a class="header-anchor" href="#首次进入直播间路径" aria-label="Permalink to &quot;首次进入直播间路径&quot;">​</a></h4><ol><li>客户端请求 <code>GET /comments/{liveVideoId}</code></li><li>服务返回最近一屏历史评论</li><li>客户端同时建立 <code>GET /stream/{liveVideoId}</code> SSE 连接</li><li>后续新评论不断通过 SSE 推送</li></ol><h4 id="上滑加载更早评论路径" tabindex="-1">上滑加载更早评论路径 <a class="header-anchor" href="#上滑加载更早评论路径" aria-label="Permalink to &quot;上滑加载更早评论路径&quot;">​</a></h4><ol><li>客户端拿到当前最老评论的时间戳</li><li>请求 <code>GET /comments/{liveVideoId}?before={timestamp}&amp;limit={n}</code></li><li>服务返回更早一页</li></ol><h4 id="mega-stream-路径" tabindex="-1">mega-stream 路径 <a class="header-anchor" href="#mega-stream-路径" aria-label="Permalink to &quot;mega-stream 路径&quot;">​</a></h4><ol><li>系统检测某直播的评论速度过高</li><li>对该直播切换到采样 / 限流模式</li><li>每个观众只收到一个代表性子集</li></ol><h2 id="参考来源" tabindex="-1">参考来源 <a class="header-anchor" href="#参考来源" aria-label="Permalink to &quot;参考来源&quot;">​</a></h2><ul><li><a href="https://www.hellointerview.com/learn/system-design/problem-breakdowns/fb-live-comments" target="_blank" rel="noreferrer">Hello Interview 官方讲解：FB Live Comments</a></li></ul>',52)])])}const u=a(c,[["render",r]]);export{b as __pageData,u as default};
